import { listAdminAchievements } from "@/modules/motivation/services/motivation.service";
import { AdminAchievementForm } from "@/modules/motivation/components/AdminMotivationForms";
export default async function AdminAchievementsPage() { const achievements = await listAdminAchievements(); return <div><h1 className="text-3xl font-bold">Achievements</h1><p className="mt-2 text-slate-600">Achievement rules are evaluated server-side after learning events.</p><AdminAchievementForm /><section className="mt-7 grid gap-4 md:grid-cols-2">{achievements.map((achievement) => <article key={achievement.id} className="rounded-xl border bg-white p-5"><div className="flex justify-between"><span className="text-3xl">{achievement.icon}</span><span className="text-xs font-semibold">{achievement.rarity}</span></div><h2 className="mt-3 text-xl font-bold">{achievement.title}</h2><p className="mt-2 text-sm text-slate-600">{achievement.description}</p><p className="mt-3 text-sm">{achievement.conditionType} · target {Number((achievement.conditionConfig as { target?: number }).target ?? 1)}</p><p className="mt-2 text-sm">+{achievement.experienceReward} XP · +{achievement.coinReward} coins</p><p className="mt-2 text-xs text-slate-500">{achievement._count.userAchievements} user records · {achievement.isActive ? "Active" : "Inactive"}</p></article>)}</section></div>; }
